// What the kobold writes for a team member's own idea, through its tool
// write_idea: the idea, the story it assumes behind it (every scene guessed,
// since nobody said it yet; written from the idea) and the problem that
// story breaks at, marked assumed. All in one write, which the store checks
// like any other; what does not fit is said, so the kobold can correct
// itself.
import { KOBOLD } from "@software-factory/core";
import { z } from "zod";
import { Refused } from "../refused.js";
import { Edit, newId } from "../records/edit.js";
const words = z.string().trim().min(1);
export const WRITE_IDEA_INPUT = {
    title: words.describe("The idea, in two to five words."),
    weThink: words.describe("What the team thinks it would do, in a sentence: “If …, <persona> would …”."),
    story: z
        .strictObject({
        title: words.describe("The story, in the persona's terms."),
        starts: z.string().describe("Where and when it starts."),
        wants: z.string().describe("What the persona wants in it."),
        scenes: z
            .array(z.strictObject({
            text: words.describe("The moment, in one short sentence with its subject, read as part of a paragraph."),
            breaks: z
                .boolean()
                .describe("True for the one scene where it breaks."),
        }))
            .min(1),
        instead: z
            .string()
            .optional()
            .describe("What the persona does instead, since it breaks."),
    })
        .describe("The story the idea assumes: every scene is guessed."),
    problem: z
        .strictObject({
        title: words.describe("The problem it breaks at, in the persona's words."),
        reading: z.string().describe("What is behind it, in a line or two."),
    })
        .describe("The problem the story breaks at, assumed."),
};
// The idea, its assumed story and problem, written at once; its id and
// what was done, in a line.
export function writeOwnIdea(store, own, written) {
    const edit = new Edit(store);
    const persona = edit.get("personas", own.persona, "persona");
    const breaking = written.story.scenes.filter((s) => s.breaks).length;
    if (breaking !== 1)
        throw new Refused(`The story breaks ${String(breaking)} times: mark exactly one scene where it breaks.`);
    const problem = edit.put("problems", {
        id: newId("problem"),
        persona: persona.id,
        title: written.problem.title,
        reading: written.problem.reading,
        by: KOBOLD,
        assumed: true,
        realProblem: null,
    });
    const idea = edit.put("ideas", {
        id: newId("idea"),
        title: written.title,
        weThink: written.weThink,
        origin: { from: "person", name: own.by },
        problems: [problem.id],
        persona: persona.id,
    });
    const { story } = written;
    edit.put("stories", {
        id: newId("story"),
        persona: persona.id,
        title: story.title,
        starts: story.starts,
        wants: story.wants,
        scenes: story.scenes.map((scene) => ({
            text: scene.text,
            where: null,
            evidence: [],
            breaks: scene.breaks,
        })),
        instead: story.instead?.trim()
            ? { text: story.instead, evidence: [] }
            : null,
        wrong: null,
        isNew: false,
        from: { idea: idea.id },
        problem: problem.id,
    });
    edit.save(store);
    return {
        idea: idea.id,
        done: `Wrote the idea “${idea.title}” with the story it assumes, “${story.title}”, every scene guessed.`,
    };
}
